<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $seller = App\Models\User::find(1); auth()->login($seller); $p = App\Models\Product::find(5); $p->estado_publicacion_id = App\Models\Product::PUBLICACION_PAUSADO; $p->save(); $req = Illuminate\Http\Request::create("/carrito/validar-stock", "GET", ["ids" => 5]); $req->setUserResolver(fn() => $seller); $ctrl = new App\Http\Controllers\Shop\ProductsController(); $res = $ctrl->validateCartStock($req)->getData(true); echo "User ID in cart req: " . ($req->user() ? $req->user()->id : "null") . "\n"; echo "Cart validation for paused product: " . json_encode($res) . "\n"; $checkoutReq = Illuminate\Http\Request::create("/checkout", "POST", ["cliente_telefono" => "12345678", "cart_payload" => json_encode([["id" => 5, "qty" => 1]])]); $checkoutReq->setUserResolver(fn() => $seller); $checkoutCtrl = new App\Http\Controllers\Shop\CheckoutController(); $checkoutRes = $checkoutCtrl->store($checkoutReq); echo "Checkout response status: " . $checkoutRes->getStatusCode() . "\n"; echo "Checkout Redirect Target: " . $checkoutRes->getTargetUrl() . "\n"; $p->estado_publicacion_id = App\Models\Product::PUBLICACION_ACTIVO; $p->save();